import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int start = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] >= '0' && buf[pos] <= '9') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt();
        long x = nextLong(), y = nextLong();
        long[] a = new long[n];
        long mx = 0;
        for (int i = 0; i < n; i++) {
            a[i] = nextLong();
            mx = Math.max(mx, a[i]);
        }
        long extra = x - y, lo = 0, hi = (mx + y - 1) / y;
        // T rounds give every task T*y; count how many main-task picks are still needed.
        while (lo < hi) {
            long t = (lo + hi) / 2, need = 0;
            for (long v : a) {
                long rest = v - t * y;
                if (rest > 0) need += (rest + extra - 1) / extra;
            }
            if (need <= t) hi = t;
            else lo = t + 1;
        }
        System.out.println(lo);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func next() string {
	skip()
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[start:pos])
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	x, y := nextInt(), nextInt()
	a := make([]int64, n)
	var mx int64
	for i := range a {
		a[i] = nextInt()
		mx = max(mx, a[i])
	}
	extra := x - y
	lo, hi := int64(0), (mx+y-1)/y
	// T rounds give every task T*y; count how many main-task picks are still needed.
	for lo < hi {
		t := (lo + hi) / 2
		var need int64
		for _, v := range a {
			if rest := v - t*y; rest > 0 {
				need += (rest + extra - 1) / extra
			}
		}
		if need <= t {
			hi = t
		} else {
			lo = t + 1
		}
	}
	fmt.Println(lo)
}
